<template><el-card shadow="never"><el-alert title="生产批次与收发单号不同。历史库存须登记真实期初批次；分配只建立批次归属，不增加库存。普通销售自动优先使用有效期较早且未过期的批次。" type="info" :closable="false" /><div style="margin:16px 0;display:flex;gap:12px"><el-input v-model="search" placeholder="商品、仓库或批次号" clearable style="width:280px" /><el-checkbox v-model="expiredOnly">仅过期批次</el-checkbox><el-button @click="load">刷新</el-button><el-button v-if="user.isAdmin||(user.isLeader&&user.department==='仓库部')" type="primary" @click="open">登记期初批次</el-button></div><el-table :data="filtered" v-loading="loading" border stripe><el-table-column prop="product_name" label="商品" min-width="150" /><el-table-column prop="warehouse_name" label="仓库" min-width="130" /><el-table-column prop="lot_no" label="批次号" min-width="150" /><el-table-column prop="quantity" label="当前数量" width="110" /><el-table-column prop="manufactured_on" label="生产日期" width="120" /><el-table-column prop="expires_on" label="有效期" width="120" /><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.expired?'danger':'success'">{{row.expired?'已过期':'正常'}}</el-tag></template></el-table-column></el-table><el-dialog v-model="visible" title="历史库存期初批次分配" width="580px"><el-form label-width="110px"><el-form-item label="库存记录"><el-select v-model="selected" filterable style="width:100%"><el-option v-for="i in options" :key="i.id" :value="i.id" :label="`${names[i.product_id]} / ${warehouses[i.warehouse_id]} / 实物数量 ${i.quantity}`" /></el-select></el-form-item><el-form-item label="批次号"><el-input v-model="form.lot_no" maxlength="64" /></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1" :precision="0" /></el-form-item><el-form-item label="生产日期"><el-date-picker v-model="form.manufactured_on" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="有效期"><el-date-picker v-model="form.expires_on" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="资料依据"><el-input v-model="form.reason" type="textarea" maxlength="255" placeholder="按实物批次标签或其他可核实资料登记" /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存分配</el-button></template></el-dialog></el-card></template>
<script setup lang="ts">
import { newRequestId } from '@/utils/requestId'
import {computed,onMounted,reactive,ref} from 'vue'
import {get,post} from '@/utils/request'
import {useUserStore} from '@/stores/user'
import {ElMessage} from 'element-plus'
const user=useUserStore(),rows=ref<any[]>([]),loading=ref(false),saving=ref(false),visible=ref(false),search=ref(''),expiredOnly=ref(false),options=ref<any[]>([]),selected=ref<number>(),names=ref<Record<number,string>>({}),warehouses=ref<Record<number,string>>({})
const form=reactive({lot_no:'',quantity:1,manufactured_on:'',expires_on:'',reason:'',request_id:''})
const filtered=computed(()=>rows.value.filter(r=>(!expiredOnly.value||r.expired)&&(!search.value||[r.product_name,r.warehouse_name,r.lot_no].some(v=>String(v||'').toLowerCase().includes(search.value.trim().toLowerCase())))))
async function load(){loading.value=true;try{rows.value=(await get<any[]>('/lots')).data||[]}catch{}finally{loading.value=false}}
async function open(){try{const [i,p,w]=await Promise.all([get<any[]>('/inventory'),get<any[]>('/products'),get<any[]>('/warehouses')]);const tracked=new Set((p.data||[]).filter(x=>x.batch_enabled).map(x=>x.id));names.value=Object.fromEntries((p.data||[]).map(x=>[x.id,x.name]));warehouses.value=Object.fromEntries((w.data||[]).map(x=>[x.id,x.name]));options.value=(i.data||[]).filter(x=>tracked.has(x.product_id)&&x.quantity>0);selected.value=undefined;Object.assign(form,{lot_no:'',quantity:1,manufactured_on:'',expires_on:'',reason:'',request_id:newRequestId()});visible.value=true}catch{}}
async function save(){const item=options.value.find(x=>x.id===selected.value);if(!item||!form.lot_no||!form.reason.trim()){ElMessage.warning('请选择库存并填写批次号和资料依据');return}saving.value=true;try{await post('/lots/opening',{...form,product_id:item.product_id,warehouse_id:item.warehouse_id});visible.value=false;ElMessage.success('已分配，实物库存未改变');await load()}catch{}finally{saving.value=false}}
onMounted(load)
</script>
